import{$ as e,Dt as t,Q as n,Y as r,ht as i,it as a,nt as o,o as s,rt as c,tt as l,yt as u}from"./chunks/framework.CuG1B4CC.js";var d=JSON.parse(`{"title":"Architecture & Data Flow","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}`),f={name:`architecture.md`};function p(s,d,f,p,m,h){let g=u(`Mermaid`);return i(),l(`div`,null,[d[1]||=n(`h1`,{id:`architecture-data-flow`,tabindex:`-1`},[c(`Architecture & Data Flow `),n(`a`,{class:`header-anchor`,href:`#architecture-data-flow`,"aria-label":`Permalink to “Architecture & Data Flow”`},`​`)],-1),d[2]||=n(`p`,null,`Meshmetal processes raw genomic sequences into searchable indexed representations via a multi-stage pipeline.`,-1),d[3]||=n(`h2`,{id:`end-to-end-data-flow`,tabindex:`-1`},[c(`End-to-End Data Flow `),n(`a`,{class:`header-anchor`,href:`#end-to-end-data-flow`,"aria-label":`Permalink to “End-to-End Data Flow”`},`​`)],-1),(i(),e(r,null,{default:t(()=>[a(g,{id:`mermaid-9`,class:`mermaid`,graph:`flowchart%20TD%0A%20%20%20%20S1%5B%22%3Cdiv%3E1.%20Download%20SRA%20Contigs%2FUnitigs%20(.zst)%20from%20S3%3C%2Fdiv%3E%22%5D%20--%3E%20S2%5B%22%3Cdiv%3E2.%20Encode%20Sequences%20to%20128-bit%20Binary%20Hash%20Codes%3Cbr%2F%3E%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22%3Cdiv%3E3.%20Deduplicate%20%26%20Combine%20Hash%20Universe%3Cbr%2F%3E%3Ci%3E(parallel_combine_sets_128_v2_log_lowmem)%3C%2Fi%3E%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22%3Cdiv%3E4.%20Generate%20Annotations%3Cbr%2F%3E%3Ci%3E(sd_vector)%3C%2Fi%3E%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S3%20--%3E%20S6%5B%22%3Cdiv%3E6.%20FAISS%20Binary%20Index%3Cbr%2F%3E%3Ci%3E(index_mmap)%3C%2Fi%3E%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S4%20--%3E%20S5%5B%22%3Cdiv%3E5.%20Build%20BRWT%20Matrix%3Cbr%2F%3E%3Ci%3E(construct_BRWT)%3C%2Fi%3E%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S5%20--%3E%20S7%5B%22%3Cdiv%3E7.%20Query%20Engine%20(query_seq.py%20%2F%20REST%20APIs)%3Cbr%2F%3EStage%201%3A%20FAISS%20Hamming%20Search%3Cbr%2F%3EStage%202%3A%20BRWT%20Accession%20Annotation%20Retrieval%3C%2Fdiv%3E%22%5D%0A%20%20%20%20S6%20--%3E%20S7%0A`})]),fallback:t(()=>[...d[0]||=[c(` Loading... `,-1)]]),_:1})),d[4]||=o(`<h2 id="stage-descriptions" tabindex="-1">Stage Descriptions <a class="header-anchor" href="#stage-descriptions" aria-label="Permalink to “Stage Descriptions”">​</a></h2><h3 id="stage-1-sequence-acquisition-preprocessing" tabindex="-1">Stage 1: Sequence Acquisition &amp; Preprocessing <a class="header-anchor" href="#stage-1-sequence-acquisition-preprocessing" aria-label="Permalink to “Stage 1: Sequence Acquisition &amp; Preprocessing”">​</a></h3><p>Raw contigs and unitigs stored as <code>.zst</code> files in Logan S3 buckets are downloaded and decompressed using multithreaded workers.</p><h3 id="stage-2-deep-metric-learning-dml-encoding" tabindex="-1">Stage 2: Deep Metric Learning (DML) Encoding <a class="header-anchor" href="#stage-2-deep-metric-learning-dml-encoding" aria-label="Permalink to “Stage 2: Deep Metric Learning (DML) Encoding”">​</a></h3><p>Sequences are passed through a fine-tuned Transformer model. Subsequences are embedded into 128-bit binary vectors where Hamming distance directly corresponds to biological sequence similarity.</p><h3 id="stage-3-universe-deduplication-combination" tabindex="-1">Stage 3: Universe Deduplication &amp; Combination <a class="header-anchor" href="#stage-3-universe-deduplication-combination" aria-label="Permalink to “Stage 3: Universe Deduplication &amp; Combination”">​</a></h3><p>Per-sample binary embedding files are combined into a global deduplicated &quot;hash universe&quot;. Memory-constrained environments use k-way merge disk-spilling sorting (<code>parallel_combine_sets_128_v2_log_lowmem</code>).</p><h3 id="stage-4-matrix-annotation-vector-generation" tabindex="-1">Stage 4: Matrix Annotation Vector Generation <a class="header-anchor" href="#stage-4-matrix-annotation-vector-generation" aria-label="Permalink to “Stage 4: Matrix Annotation Vector Generation”">​</a></h3><p>For each sample, a bit vector (<code>sd_vector</code>) is generated indicating which hashes from the universe appear in that sample.</p><h3 id="stage-5-brwt-compression" tabindex="-1">Stage 5: BRWT Compression <a class="header-anchor" href="#stage-5-brwt-compression" aria-label="Permalink to “Stage 5: BRWT Compression”">​</a></h3><p>All sample bit vectors are combined into a compressed Binary Relation Wavelet Tree (BRWT). Arity relaxation reduces storage while maintaining rapid row/column lookup.</p><h3 id="stage-6-standalone-faiss-index-creation" tabindex="-1">Stage 6: Standalone FAISS Index Creation <a class="header-anchor" href="#stage-6-standalone-faiss-index-creation" aria-label="Permalink to “Stage 6: Standalone FAISS Index Creation”">​</a></h3><p>The unique 128-bit hash universe is indexed into a custom <code>IndexBinaryHash</code> structure supporting 16-bit prefix buckets, memory mapping (<code>mmap</code>), and REST API endpoints.</p><h3 id="stage-7-two-stage-query-retrieval" tabindex="-1">Stage 7: Two-Stage Query Retrieval <a class="header-anchor" href="#stage-7-two-stage-query-retrieval" aria-label="Permalink to “Stage 7: Two-Stage Query Retrieval”">​</a></h3><ul><li><strong>Stage 1 (FAISS)</strong>: Query sequence embeddings are matched against the 128-bit hash index to retrieve candidate hash IDs within a specified Hamming distance radius.</li><li><strong>Stage 2 (BRWT)</strong>: Matched hash IDs are queried against the BRWT server to resolve the precise SRA run accession IDs and compute coverage metrics.</li></ul>`,15)])}var m=s(f,[[`render`,p]]);export{d as __pageData,m as default};